//! Generated source files, which nobody can fix at the source.

const HEADER_LINES: usize = 15;

fn is_comment_line(line: &str) -> bool {
    let trimmed = line.trim_start();
    ["//", "#", "/*", "*"]
        .iter()
        .any(|opener| trimmed.starts_with(opener))
}

/// True when a comment among the first 15 lines says `@generated`, or says
/// both `generated` and `DO NOT EDIT` (case-insensitive).
pub(crate) fn is_generated(text: &str) -> bool {
    text.lines()
        .take(HEADER_LINES)
        .filter(|line| is_comment_line(line))
        .map(str::to_lowercase)
        .any(|line| {
            line.contains("@generated")
                || (line.contains("generated") && line.contains("do not edit"))
        })
}

#[cfg(test)]
mod tests {
    use super::is_generated;

    #[test]
    fn a_mockgen_header_marks_a_go_file() {
        assert!(is_generated(
            "// Code generated by MockGen. DO NOT EDIT.\npackage m\n"
        ));
    }

    #[test]
    fn a_prost_header_marks_a_rust_file() {
        assert!(is_generated("// This file is @generated by prost-build.\n"));
    }

    #[test]
    fn a_protoc_python_header_marks_a_python_file() {
        assert!(is_generated(
            "# Generated by the protocol buffer compiler.  DO NOT EDIT!\n"
        ));
    }

    #[test]
    fn a_protoc_gen_es_header_marks_a_ts_file() {
        assert!(is_generated("// @generated by protoc-gen-es\n"));
    }

    #[test]
    fn a_doc_comment_mentioning_generated_alone_is_hand_written() {
        assert!(!is_generated(
            "/// Parses the generated output.\nfn f() {}\n"
        ));
    }

    #[test]
    fn a_marker_after_line_fifteen_is_ignored() {
        let mut text = "// header\n".repeat(15);
        text.push_str("// @generated\n");
        assert!(!is_generated(&text));
        let mut inside = "// header\n".repeat(14);
        inside.push_str("// @generated\n");
        assert!(is_generated(&inside));
    }

    #[test]
    fn a_marker_in_a_string_literal_is_ignored() {
        assert!(!is_generated("let s = \"// @generated\";\n"));
    }
}
